      "source_ref": "Q-002"
    },
    "leistungswerte": {
      "version": "2026.1",
      "valid_until": "2026-12-31",
      "criticality": "A",
      "source_ref": "Q-005"
    },
    "nba_bewertungsmerkmale": {
